\eqalign{g_i(x) 
&=\Bover{g(x)h_i(x)}{h_1(x)+h_2(x)} 
  \text{ if }x\in\dom g\cap\dom h_1\cap\dom h_2 
  \text{ and }h_1(x)+h_2(x)>0,\cr 
&=0\text{ for other }x\in X.\cr}

